-
-	private static void procType(Field f, TraceChangeType<?, ?> type) {
-		String kind = f.getDeclaringClass().getSimpleName();
-		if (kind.startsWith("Trace")) {
-			kind = kind.substring("Trace".length());
-		}
-		if (kind.endsWith("ChangeType")) {
