+			return this;
+		}
+
+		@Override
+		public boolean hasNext() {
+			if (index == -1) {
+				index = findNext();
+			}
+			return 0 <= index && index < dieOffsets.length;
+		}
+
+		@Override
+		public DIEAggregate next() {
+			if (!hasNext()) {
+				throw new NoSuchElementException();
+			}
