-			index = -index - 1;
-		}
-		else {
-			components.remove(index);
-		}
-		if (deltaOrdinal != 0) {
-			adjustOffsets(index, newOffset, deltaOrdinal, 0);
-		}
-		components.add(index, newDtc);
-		if (deltaOrdinal != 0) {
-			numComponents += deltaOrdinal;
-		}
-		return newDtc;
-	}
