+		 * def.getOrdinal(), def.getName()); export("PROTO_PARAMETER_DATATYPE",
+		 * def.getName(), dtID(def.getDataType())); exportType(def.getDataType()); } }
+		 */
+		DataType returnType = proto.getReturnType();
