+			"TaintProvider: clearTaint() - state clearTaint() and highligher apply highlights.");
+		matchCount = 0;
+		state.clearTaint();
+		highlighter.clearHighlights();
+		cachedHighlightByAddress.clear();
+		cachedHighlightsByToken.clear();
+		highlighter.applyHighlights();
+	}
