+			else if (hv != null) {
+				writer.println("\tCVar_SourceInfo(vn, SOURCE_INFO_NAME_KEY, \"" +
+					TaintState.hvarName(token) + "\"),");
+			}
+			else {
+				writer.println("\tCVar_Name(vn, \"" + token.getText() + "\"),");
+			}
+			if (!allAccess) {
+				writer.println("\tp = \"\",");
+			}
+			writer.println("\tVertex(vn, p).");
