+			String dstId = SarifUtils.getEdgeDest(edgeId);
+			LogicalLocation[] dstNodes = SarifUtils.getNodeLocs(dstId);
+			for (LogicalLocation lloc : dstNodes) {
+				vset.add(new TaintQueryResult(result, run, lloc));
+			}
+		}
+	}
