+	private MatchedFunctionComparisonModel createTestModel() {
+		MatchedFunctionComparisonModel m = new MatchedFunctionComparisonModel();
+		m.addMatch(a1, b1);
+		m.addMatch(a1, b2);
+		m.addMatch(a2, b2);
+		m.addMatch(a2, b3);
+		m.addMatch(a3, b1);
