+		this.streamEnd = streamEnd;
+		this.pointerSize = pointerSize;
+		this.opcodeBase = opcodeBase;
+		this.lineBase = lineBase;
+		this.lineRange = lineRange;
+		this.minInstrLen = minInstrLen;
